export class TextileScienceEngine {
  public getSpecById(id: string): TextileTechnicalSpec | undefined {
    return TEXTILE_TECHNICAL_SPECS_DATABASE.find(s => s.specId === id);
  }
  public getSpecsByMill(mill: string): TextileTechnicalSpec[] {
    return TEXTILE_TECHNICAL_SPECS_DATABASE.filter(s => s.millName === mill);
  }
}
export const textileScienceEngine = new TextileScienceEngine();
